const state = { playing: false, paused: false, score: 0, combo: 0, streak: 0, hits: 0, attempts: 0, misses: 0, best: Number(localStorage.getItem('emojiTilesBest') || 0), speed: FIXED_TILE_SPEED, timer: null, chartTimer: null, fallbackTimer: null, audio: null, elapsed: 0, chartPulse: 0, chartIndex: 0, chartEvents: [], chartClockMode: 'performance', chartClockStartedAt: 0, chartClockBase: 0, chartClockOffset: 0, chartPausedAt: 0, fallbackBeatIndex: -1, preparedSongFile: '', loadToken: 0, bpm: 128, musicStarted: false, usingFallback: false, volume: .7, song: { file: 'solarflex-roblox-minecraft-fortnite-video-game-music-491492.mp3', bpm: 128, title: 'Solarflex', artist: 'Game Beat' } };
const recorder = { active: false, events: [], startedAt: 0, useAudioClock: false };
bestElement.textContent = formatScore(state.best);

function formatScore(value) { return String(value).padStart(6, '0'); }
function updateHud() { scoreElement.textContent = formatScore(state.score); comboElement.textContent = `x${state.combo}`; streakElement.textContent = state.streak; accuracyElement.textContent = `${state.attempts ? Math.round(state.hits / state.attempts * 100) : 100}%`; missesElement.textContent = state.misses; }
function playTone(lane) { if (!state.audio || state.volume === 0) return; const oscillator = state.audio.createOscillator(); const gain = state.audio.createGain(); oscillator.frequency.value = [261.6, 329.6, 392, 523.3][lane]; oscillator.type = 'sine'; gain.gain.setValueAtTime(.045 * state.volume, state.audio.currentTime); gain.gain.exponentialRampToValueAtTime(.001, state.audio.currentTime + .18); oscillator.connect(gain).connect(state.audio.destination); oscillator.start(); oscillator.stop(state.audio.currentTime + .18); }
function showFeedback(text, good = true) { feedback.textContent = text; feedback.style.color = good ? 'var(--cyan)' : 'var(--coral)'; feedback.classList.remove('show'); void feedback.offsetWidth; feedback.classList.add('show'); }
function readChartClock() { if (state.paused) return state.chartPausedAt; if (state.chartClockMode === 'audio' && !music.paused) return Math.max(0, music.currentTime + state.chartClockOffset); return state.chartClockBase + (performance.now() - state.chartClockStartedAt) / 1000; }
function useChartClock(mode, baseSeconds = readChartClock()) { state.chartClockMode = mode; if (mode === 'audio') state.chartClockOffset = baseSeconds - music.currentTime; else { state.chartClockBase = baseSeconds; state.chartClockStartedAt = performance.now(); } }
function playFallbackBeat() { if (!state.audio || state.volume === 0) return; const beat = Math.floor(state.elapsed / (60 / state.bpm)) % 8; const frequencies = [130.8, 164.8, 196, 261.6, 196, 164.8, 146.8, 196]; const oscillator = state.audio.createOscillator(); const gain = state.audio.createGain(); oscillator.type = beat % 4 === 0 ? 'triangle' : 'sine'; oscillator.frequency.value = frequencies[beat]; gain.gain.setValueAtTime(.055 * state.volume, state.audio.currentTime); gain.gain.exponentialRampToValueAtTime(.001, state.audio.currentTime + .32); oscillator.connect(gain).connect(state.audio.destination); oscillator.start(); oscillator.stop(state.audio.currentTime + .32); }
function stopFallbackMusic() { clearInterval(state.fallbackTimer); state.fallbackTimer = null; }
function startFallbackMusic() { if (state.usingFallback) return; const currentSeconds = readChartClock(); state.usingFallback = true; state.fallbackBeatIndex = Math.floor(currentSeconds * state.bpm / 60) - 1; if (state.playing && !state.paused) useChartClock('performance', currentSeconds); songStatus.textContent = `${state.song.title} · modo audio compatible`; }
function endGame(message = '¡Fallaste!', completed = false) { if (!state.playing) return; state.playing = false; state.paused = false; clearInterval(state.timer); cancelAnimationFrame(state.chartTimer); stopFallbackMusic(); music.pause(); pauseOverlay.classList.add('is-hidden'); startOverlay.classList.add('is-hidden'); gameoverLabel.textContent = completed ? 'CANCIÓN COMPLETADA' : 'RITMO INTERRUMPIDO'; gameoverTitle.textContent = completed ? '¡Bien jugado!' : 'Has fallado'; gameoverOverlay.classList.remove('is-hidden'); showFeedback(message, completed); playfield.querySelectorAll('.tile').forEach(tile => tile.style.animationPlayState = 'paused'); updateHud(); }
function syncTileSpeed() { playfield.querySelectorAll('.tile:not(.hit):not(.missed)').forEach(tile => { tile.style.animationDuration = `${state.speed}s`; }); }
function createTile(lane) { if (!state.playing || state.paused || lane === null || lane === undefined) return; const tile = document.createElement('div'); const emojis = ['✨', '🌈', '💫', '🎵']; tile.className = 'tile'; tile.dataset.lane = lane; tile.dataset.spawn = Date.now(); tile.style.animationDuration = `${state.speed}s`; tile.innerHTML = `<span>${emojis[lane]}</span>`; tile.addEventListener('pointerdown', event => { event.preventDefault(); hitTile(tile); }); playfield.appendChild(tile); }
function createChartTilesForPulse() { while (state.chartIndex < state.chartEvents.length && state.chartEvents[state.chartIndex].time <= state.chartPulse + .001) { const event = state.chartEvents[state.chartIndex]; createTile({ A: 0, S: 1, D: 2, F: 3 }[event.note.toUpperCase()]); state.chartIndex++; } }
function updateChartClock() { if (!state.playing || state.paused) return; state.elapsed = readChartClock(); state.chartPulse = state.elapsed * state.bpm / 60; createChartTilesForPulse(); if (state.usingFallback) { const beatNumber = Math.floor(state.chartPulse); if (beatNumber > state.fallbackBeatIndex) { state.fallbackBeatIndex = beatNumber; playFallbackBeat(); } } state.chartTimer = requestAnimationFrame(updateChartClock); }
function registerMiss(tile) { state.attempts++; state.misses++; state.combo = 0; state.streak = 0; tile.remove(); showFeedback('Fallaste', false); updateHud(); }
function hitTile(tile) { if (!state.playing || state.paused || tile.classList.contains('hit')) return; const tileTop = tile.getBoundingClientRect().top; const hitLine = playfield.querySelector('.hit-line').getBoundingClientRect(); const lineTop = hitLine.top + hitLine.height / 2; const distance = Math.abs(tileTop + tile.offsetHeight / 2 - lineTop); const perfectWindow = 60; const hitWindow = 125; if (distance > hitWindow) { registerMiss(tile); return; } state.attempts++; state.hits++; state.combo++; state.streak++; state.score += 10 + Math.min(state.combo, 30) * 2; tile.remove(); playTone(Number(tile.dataset.lane)); showFeedback(distance <= perfectWindow ? '¡Perfecto!' : 'Bien'); updateHud(); if (state.score > state.best) { state.best = state.score; localStorage.setItem('emojiTilesBest', state.best); bestElement.textContent = formatScore(state.best); } }
function configureSong(song = state.song) { state.song = song; state.bpm = song.bpm; music.pause(); music.src = song.file; music.load(); if (songStatus) songStatus.textContent = `${song.title} · ${song.artist} · ${state.bpm} BPM`; if (activeSongTitle) activeSongTitle.textContent = song.title; }
function setLoadingState(progress, status) { loadingProgress.style.width = `${progress}%`; loadingStatus.textContent = status; }
function prepareSelectedSong(song) { const token = ++state.loadToken; state.playing = false; clearInterval(state.timer); cancelAnimationFrame(state.chartTimer); stopFallbackMusic(); music.pause(); state.song = song; loadingTitle.textContent = song.title; setLoadingState(8, 'Cargando canción...'); loadingOverlay.classList.remove('is-hidden'); startOverlay.classList.add('is-hidden'); configureSong(song); setLoadingState(36, 'Preparando interfaz...'); state.chartEvents = [...(SONG_CHARTS[song.file] || [])].map(event => ({ ...event })).sort((first, second) => first.time - second.time); state.preparedSongFile = song.file; setLoadingState(68, `${state.chartEvents.length} notas listas`); const audioReady = new Promise(resolve => { let resolved = false; const finish = () => { if (resolved) return; resolved = true; music.removeEventListener('canplay', finish); music.removeEventListener('canplaythrough', finish); music.removeEventListener('error', finish); resolve(); }; music.addEventListener('canplay', finish); music.addEventListener('canplaythrough', finish); music.addEventListener('error', finish); setTimeout(finish, 1400); }); audioReady.then(() => { if (token !== state.loadToken) return; setLoadingState(92, 'Todo listo para jugar'); setTimeout(() => { if (token !== state.loadToken) return; setLoadingState(100, 'Listo'); loadingOverlay.classList.add('is-hidden'); startOverlay.classList.remove('is-hidden'); }, 220); }); }
function playMusic() { music.volume = state.volume; const playRequest = music.play(); if (playRequest) playRequest.then(() => { if (state.playing && !state.paused) useChartClock('audio'); state.usingFallback = false; stopFallbackMusic(); songStatus.textContent = `${state.song.title} · ${state.song.artist} · reproduciendo`; }).catch(error => { if (error.name === 'NotAllowedError') songStatus.textContent = 'Pulsa Comenzar para activar el audio'; else startFallbackMusic(); }); }
function renderRecordedChart() { const secondsPerBeat = 60 / state.bpm; const sortedEvents = [...recorder.events].sort((first, second) => first.seconds - second.seconds); const rows = sortedEvents.map(event => `\t\t{ time: ${(event.seconds / secondsPerBeat).toFixed(2)}, note: '${event.note}' }`); chartOutput.value = rows.length ? `'${state.song.file}': [\n${rows.join(',\n')}\n]` : `'${state.song.file}': [\n\t// Inicia la canción y pulsa Z, X, coma o punto para grabar notas.\n]`; recordedNotes.textContent = sortedEvents.length ? sortedEvents.map(event => `${event.note} · ${event.seconds.toFixed(2)} s`).join('   |   ') : 'Aún no hay notas grabadas'; }
function getRecorderSeconds() { return recorder.useAudioClock ? music.currentTime : (performance.now() - recorder.startedAt) / 1000; }
function startRecording() { state.audio = state.audio || new (window.AudioContext || window.webkitAudioContext)(); if (state.audio.state === 'suspended') state.audio.resume(); recorder.active = true; recorder.events = []; recorder.startedAt = performance.now(); recorder.useAudioClock = false; music.pause(); music.currentTime = 0; music.volume = state.volume; renderRecordedChart(); recordingStatus.classList.add('is-recording'); recordingStatus.innerHTML = '<span class="recording-dot"></span> Iniciando reproducción...'; recordStartButton.disabled = true; recordStopButton.disabled = false; const playPromise = music.play(); if (playPromise) playPromise.then(() => { if (!recorder.active) return; recorder.useAudioClock = true; recorder.startedAt = performance.now(); recordingStatus.innerHTML = '<span class="recording-dot"></span> Grabando · pulsa Z, X, coma o punto'; }).catch(() => { if (!recorder.active) return; startFallbackMusic(); recordingStatus.innerHTML = '<span class="recording-dot"></span> Grabando con reloj local · pulsa Z, X, coma o punto'; }); }
function stopRecording() { recorder.active = false; stopFallbackMusic(); music.pause(); recordStartButton.disabled = false; recordStopButton.disabled = true; recordingStatus.classList.remove('is-recording'); recordingStatus.innerHTML = `<span class="recording-dot"></span> Grabación detenida · ${recorder.events.length} notas`; renderRecordedChart(); }
function openRecorder() { settingsBackdrop.classList.add('is-hidden'); recorderSong.textContent = `${state.song.title} · ${state.song.artist} · ${state.bpm} BPM`; recorder.events = []; renderRecordedChart(); recorderBackdrop.classList.remove('is-hidden'); }
function closeRecorder() { if (recorder.active) stopRecording(); recorderBackdrop.classList.add('is-hidden'); }
function getKeyboardLane(event) { const laneByCode = { KeyZ: 0, KeyX: 1, Comma: 2, Period: 3 }; if (Object.hasOwn(laneByCode, event.code)) return laneByCode[event.code]; return { z: 0, x: 1, ',': 2, '.': 3 }[event.key.toLowerCase()]; }
function startGame() { state.audio = state.audio || new (window.AudioContext || window.webkitAudioContext)(); if (state.audio.state === 'suspended') state.audio.resume(); if (state.preparedSongFile !== state.song.file) prepareSelectedSong(state.song); state.playing = true; state.paused = false; state.score = 0; state.combo = 0; state.streak = 0; state.hits = 0; state.attempts = 0; state.chartPulse = 0; state.chartIndex = 0; state.fallbackBeatIndex = -1; const offsetSeconds = CHART_OFFSETS_SECONDS[state.song.file] || 0; const offsetPulses = offsetSeconds / (60 / state.bpm); state.chartEvents = [...(SONG_CHARTS[state.song.file] || [])].map(event => ({ ...event, time: event.time + offsetPulses })).sort((first, second) => first.time - second.time); state.speed = FIXED_TILE_SPEED * 100 / Number(speedControl.value); state.elapsed = 0; state.musicStarted = true; state.usingFallback = false; state.chartClockMode = 'performance'; state.chartClockBase = 0; state.chartClockStartedAt = performance.now(); state.chartClockOffset = 0; state.chartPausedAt = 0; music.currentTime = 0; playMusic(); playfield.querySelectorAll('.tile').forEach(tile => tile.remove()); startOverlay.classList.add('is-hidden'); loadingOverlay.classList.add('is-hidden'); pauseOverlay.classList.add('is-hidden'); gameoverOverlay.classList.add('is-hidden'); updateHud(); clearInterval(state.timer); cancelAnimationFrame(state.chartTimer); createChartTilesForPulse(); state.chartTimer = requestAnimationFrame(updateChartClock); }
function togglePause() { if (!state.playing) return; if (!state.paused) { state.chartPausedAt = readChartClock(); state.paused = true; music.pause(); clearInterval(state.timer); cancelAnimationFrame(state.chartTimer); stopFallbackMusic(); } else { state.paused = false; useChartClock('performance', state.chartPausedAt); if (state.usingFallback) state.fallbackBeatIndex = Math.floor(state.chartPausedAt * state.bpm / 60) - 1; else playMusic(); state.chartTimer = requestAnimationFrame(updateChartClock); } pauseOverlay.classList.toggle('is-hidden', !state.paused); pauseButton.textContent = state.paused ? '▶' : 'Ⅱ'; playfield.querySelectorAll('.tile').forEach(tile => tile.style.animationPlayState = state.paused ? 'paused' : 'running'); }
document.querySelector('#enter-game-button').addEventListener('click', () => { landingScreen.classList.add('is-hidden'); gameScreen.classList.remove('is-hidden'); songListView.classList.remove('is-hidden'); gameCard.classList.add('is-hidden'); });
document.querySelector('#home-button').addEventListener('click', event => { event.preventDefault(); document.body.classList.remove('game-active'); state.loadToken++; loadingOverlay.classList.add('is-hidden'); if (state.playing) { state.playing = false; clearInterval(state.timer); stopFallbackMusic(); music.pause(); } playfield.querySelectorAll('.tile').forEach(tile => tile.remove()); startOverlay.classList.remove('is-hidden'); pauseOverlay.classList.add('is-hidden'); gameoverOverlay.classList.add('is-hidden'); gameCard.classList.add('is-hidden'); songListView.classList.remove('is-hidden'); gameScreen.classList.add('is-hidden'); landingScreen.classList.remove('is-hidden'); });
songButtons.forEach(button => button.addEventListener('click', () => { const song = { file: button.dataset.song, bpm: Number(button.dataset.bpm), title: button.dataset.title, artist: button.dataset.artist }; document.body.classList.add('game-active'); songListView.classList.add('is-hidden'); gameCard.classList.remove('is-hidden'); prepareSelectedSong(song); }));
document.querySelector('#start-button').addEventListener('click', () => { state.misses = 0; startGame(); }); document.querySelector('#restart-button').addEventListener('click', () => { state.misses = 0; startGame(); }); document.querySelector('#resume-button').addEventListener('click', togglePause); pauseButton.addEventListener('click', togglePause);
document.querySelector('#gameover-home-button').addEventListener('click', () => { document.body.classList.remove('game-active'); state.playing = false; state.paused = false; clearInterval(state.timer); stopFallbackMusic(); music.pause(); playfield.querySelectorAll('.tile').forEach(tile => tile.remove()); pauseOverlay.classList.add('is-hidden'); gameoverOverlay.classList.add('is-hidden'); startOverlay.classList.remove('is-hidden'); gameCard.classList.add('is-hidden'); songListView.classList.remove('is-hidden'); });
document.querySelector('#back-to-songs-button').addEventListener('click', () => { document.body.classList.remove('game-active'); state.loadToken++; state.playing = false; state.paused = false; clearInterval(state.timer); stopFallbackMusic(); music.pause(); music.currentTime = 0; loadingOverlay.classList.add('is-hidden'); playfield.querySelectorAll('.tile').forEach(tile => tile.remove()); pauseOverlay.classList.add('is-hidden'); gameoverOverlay.classList.add('is-hidden'); startOverlay.classList.remove('is-hidden'); gameCard.classList.add('is-hidden'); songListView.classList.remove('is-hidden'); });
function toggleSettings(open) { settingsBackdrop.classList.toggle('is-hidden', !open); if (open) volumeControl.focus(); }
settingsButton.addEventListener('click', () => toggleSettings(true)); closeSettings.addEventListener('click', () => toggleSettings(false)); settingsDone.addEventListener('click', () => toggleSettings(false)); settingsBackdrop.addEventListener('click', event => { if (event.target === settingsBackdrop) toggleSettings(false); });
volumeControl.addEventListener('input', () => { state.volume = Number(volumeControl.value) / 100; volumeValue.textContent = `${volumeControl.value}%`; music.volume = state.volume; });
speedControl.addEventListener('input', () => { const speedPercent = Number(speedControl.value); state.speed = FIXED_TILE_SPEED * 100 / speedPercent; speedValue.textContent = `${speedPercent}%`; syncTileSpeed(); });
openRecorderButton.addEventListener('click', openRecorder); closeRecorderButton.addEventListener('click', closeRecorder); recordStartButton.addEventListener('click', startRecording); recordStopButton.addEventListener('click', stopRecording); recorderBackdrop.addEventListener('click', event => { if (event.target === recorderBackdrop) closeRecorder(); });
copyChartButton.addEventListener('click', async () => { try { await navigator.clipboard.writeText(chartOutput.value); } catch { chartOutput.focus(); chartOutput.select(); document.execCommand('copy'); } copyChartButton.innerHTML = 'Copiado <span>✓</span>'; setTimeout(() => { copyChartButton.innerHTML = 'Copiar código <span>⧉</span>'; }, 1400); });
configureSong();
document.addEventListener('keydown', event => { if (event.code === 'Escape' && !recorderBackdrop.classList.contains('is-hidden')) { closeRecorder(); return; } if (event.code === 'Escape' && !settingsBackdrop.classList.contains('is-hidden')) { toggleSettings(false); return; } const lane = getKeyboardLane(event); if (recorder.active && lane !== undefined && !event.repeat) { recorder.events.push({ seconds: getRecorderSeconds(), note: ['A', 'S', 'D', 'F'][lane] }); renderRecordedChart(); return; } if (event.code === 'Space') { event.preventDefault(); togglePause(); return; } if (lane === undefined || !state.playing || state.paused) return; const tiles = [...playfield.querySelectorAll(`.tile[data-lane="${lane}"]`)].sort((a, b) => b.getBoundingClientRect().top - a.getBoundingClientRect().top); if (tiles[0]) hitTile(tiles[0]); });
setInterval(() => { if (!state.playing || state.paused) return; playfield.querySelectorAll('.tile').forEach(tile => { if (tile.getBoundingClientRect().top > playfield.getBoundingClientRect().bottom - 35 && !tile.classList.contains('missed')) registerMiss(tile); }); }, 120); music.addEventListener('ended', () => { if (recorder.active) { stopRecording(); return; } if (state.playing) endGame('¡Partida completa!', true); }); music.addEventListener('error', () => { if (state.playing) startFallbackMusic(); });